    { "x": 80.0, "y": 15.0, "correct": false, "label": "Lune", "feedbackText": "Non : la lune est un disque lumineux en haut à droite du ciel." },
    { "x": 50.0, "y": 30.0, "correct": false, "label": "Ciel tourbillonnant", "feedbackText": "Non : le ciel est rempli de spirales et de tourbillons blancs qui donnent un mouvement au paysage." },
    { "x": 50.0, "y": 75.0, "correct": false, "label": "Village", "feedbackText": "Non : le village montre des toits sombres et des maisons en contrebas, sous le ciel." },
    { "x": 30.0, "y": 20.0, "correct": false, "label": "Étoiles", "feedbackText": "Non : les étoiles sont de petits points lumineux parsemés dans le ciel nocturne." }
  ],
  "noneSelectedFeedback": "Tu n’as cliqué sur rien qui ressemble au cyprès. Cherche bien près du bas de l’image, à gauche."
}
